import{_ as e,o as t,c as r,x as o}from"./chunks/framework.DzQQ_lrg.js";const f=JSON.parse('{"title":"真实案例","description":"从可核对的事件与制度流程出发，理解接口、反馈和行动之间的区别。","frontmatter":{"title":"真实案例","description":"从可核对的事件与制度流程出发，理解接口、反馈和行动之间的区别。"},"headers":[],"relativePath":"cases/index.md","filePath":"cases/index.md"}'),n={name:"cases/index.md"};function h(i,a,l,s,p,c){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="在真实事件里理解概念" tabindex="-1">在真实事件里理解概念 <a class="header-anchor" href="#在真实事件里理解概念" aria-label="Permalink to &quot;在真实事件里理解概念&quot;">​</a></h1><p>案例首先回答发生了什么，再说明它帮助我们注意哪一项区别。事件事实、来源的解释，以及借助理论提出的阅读问题，各自保持身份。</p><h2 id="reading-routes" tabindex="-1">先从哪个问题读起 <a class="header-anchor" href="#reading-routes" aria-label="Permalink to &quot;先从哪个问题读起 {#reading-routes}&quot;">​</a></h2><p>不必按下面的排列顺序通读。可以先选一个想分清的问题，沿“概念图解、案例、原文”读一遍。这只是阅读顺序，不是把几份材料串成一项理论检验。</p><ul><li><strong>信息已经收到，下一步究竟改变了吗？</strong> 先看概念图解<a href="./../concepts/feedback.html">反馈与学习</a>，再读<a href="./flint-water-feedback.html">弗林特饮水投诉案例</a>，最后回到<a href="./../theory/part-03.html#section-3-3">§3.3 D2 有效反馈</a>。两个方向都要留意：收到、转交、结案，各自只说明那一步发生了；问题还没解决，也不能据此断定完全没有有效反馈。</li><li><strong>一张图回答了什么，又没有回答什么？</strong> 先看概念图解<a href="./../concepts/representation.html">表示与尺度</a>，再读<a href="./representation-hurricane-cone.html">伊恩飓风预报锥案例</a>，最后回到<a href="./../theory/part-03.html#section-3-4">§3.4 D3 尺度变换</a>。预报锥画的是风暴中心的可能路径，不是全部灾害影响；范围有限，也不取消它本来提供的信息。</li><li><strong>服务回来了，哪些已经恢复，哪些还没有？</strong> 先看概念图解<a href="./../concepts/recovery.html">支持与恢复</a>，再读<a href="./gitlab-recovery.html">GitLab 数据库事故案例</a>，最后回到<a href="./../theory/part-06.html#section-6-6">§6.6 CM-LOAD 负荷、容量与恢复</a>。分别记下已经恢复的功能、它依赖的条件，以及没有找回或尚未核实的部分。</li></ul><h2 id="一份数据-怎样失去了共同含义" tabindex="-1">一份数据，怎样失去了共同含义？ <a class="header-anchor" href="#一份数据-怎样失去了共同含义" aria-label="Permalink to &quot;一份数据，怎样失去了共同含义？&quot;">​</a></h2><p>1999 年火星气候轨道器失联。NASA 调查报告指出了地面软件与导航软件之间的单位不一致，也讨论了验证和沟通环节的问题。</p><p>从这件事看<strong>接口、表示与整链</strong>：数据文件被交付，不等于同一个量已经被正确理解和使用。</p><p><a href="./mars-climate-orbiter.html">阅读火星气候轨道器案例 →</a></p><h2 id="发现问题之后-谁能让下一步改变" tabindex="-1">发现问题之后，谁能让下一步改变？ <a class="header-anchor" href="#发现问题之后-谁能让下一步改变" aria-label="Permalink to &quot;发现问题之后，谁能让下一步改变？&quot;">​</a></h2><p>丰田公开介绍的安灯与自働化流程，把异常发现、呼叫、响应和必要时停止生产连接起来。</p><p>从这个流程看<strong>反馈与执行条件</strong>：信息能够被看见之后，还要有可响应的人、权限和实际动作。</p><p><a href="./toyota-andon.html">阅读丰田安灯案例 →</a></p><h2 id="赢得选举-是否也获得了决定-谁能监督自己-的权力" tabindex="-1">赢得选举，是否也获得了决定“谁能监督自己”的权力？ <a class="header-anchor" href="#赢得选举-是否也获得了决定-谁能监督自己-的权力" aria-label="Permalink to &quot;赢得选举，是否也获得了决定“谁能监督自己”的权力？&quot;">​</a></h2><p>这份专题研究通过记者准入、受保护任职与信息公开争议，分别讨论政治支持、法律权限、监督手段和实际纠错。报告保留完整论证、竞争解释与二十项来源，证据截止为 2026 年 10 月 14 日。</p><p><a href="./democratic-authorization.html">阅读民主授权的边界 →</a></p><h2 id="服务回来了-是否就等于数据全部找回" tabindex="-1">服务回来了，是否就等于数据全部找回？ <a class="header-anchor" href="#服务回来了-是否就等于数据全部找回" aria-label="Permalink to &quot;服务回来了，是否就等于数据全部找回？&quot;">​</a></h2><p>2017 年 GitLab.com 主数据库被误删后，团队用一份约六小时前的快照恢复了服务，快照之后的数据库修改没有找回。</p><p>从这件事看<strong>恢复声明的范围</strong>：服务重新可用是真实的结果，却不能替代“数据完整”这个更宽的目标；有备份流程，也不等于有可用的备份。</p><p><a href="./gitlab-recovery.html">阅读 GitLab 恢复案例 →</a></p><h2 id="投诉收到了回信-说明它改变了什么吗" tabindex="-1">投诉收到了回信，说明它改变了什么吗？ <a class="header-anchor" href="#投诉收到了回信-说明它改变了什么吗" aria-label="Permalink to &quot;投诉收到了回信，说明它改变了什么吗？&quot;">​</a></h2><p>2014 年至 2016 年，美国环保署第五区收到 87 件有关弗林特饮水的居民投诉，多数以格式信回复。四年后的跟进审计发现，环保署接收线索的两个入口里，一个有了评估风险、记录处理结果的规程，另一个仍只能转交线索和开启、关闭案件。</p><p>从这两份审计看<strong>到达、回复、结案与实际改变</strong>：四种记录说明的东西并不一样。</p><p><a href="./flint-water-feedback.html">阅读弗林特饮水投诉案例 →</a></p><h2 id="没拿到出租车执照-就等于没有学会吗" tabindex="-1">没拿到出租车执照，就等于没有学会吗？ <a class="header-anchor" href="#没拿到出租车执照-就等于没有学会吗" aria-label="Permalink to &quot;没拿到出租车执照，就等于没有学会吗？&quot;">​</a></h2><p>一项对伦敦出租车学员的纵向研究里，取得资格和没有取得资格的学员，复测时在伦敦地标空间关系判断上都优于对照者；后部海马灰质的增加，却只见于取得资格的学员。</p><p>从这项研究看<strong>资格、任务表现与学习机制</strong>：三者是不同的记录，不能互相代替。</p><p><a href="./london-taxi-learning.html">阅读伦敦出租车学员案例 →</a></p><h2 id="登陆点落在预报锥里-风暴潮的风险就画出来了吗" tabindex="-1">登陆点落在预报锥里，风暴潮的风险就画出来了吗？ <a class="header-anchor" href="#登陆点落在预报锥里-风暴潮的风险就画出来了吗" aria-label="Permalink to &quot;登陆点落在预报锥里，风暴潮的风险就画出来了吗？&quot;">​</a></h2><p>2022 年飓风伊恩在佛罗里达西南部登陆。美国国家飓风中心的事后报告认为各期预报锥都包含了登陆点；同一份报告也记录了风暴潮对路径的敏感，以及相距不到 30 英里的两处测点水位相差悬殊。</p><p>从这份报告看<strong>一种表示回答的是哪个问题</strong>：预报锥画的是风暴中心的可能路径，不是风、雨或潮水的范围。</p><p><a href="./representation-hurricane-cone.html">阅读飓风伊恩与预报锥案例 →</a></p><h2 id="档案有人接收-能否说机构已经有序退场" tabindex="-1">档案有人接收，能否说机构已经有序退场？ <a class="header-anchor" href="#档案有人接收-能否说机构已经有序退场" aria-label="Permalink to &quot;档案有人接收，能否说机构已经有序退场？&quot;">​</a></h2><p>大西洋慈善基金会（The Atlantic Philanthropies）在 2020 年结束工作之前，出资安排康奈尔大学图书馆接收它的档案。馆方的说明写了收的是哪几类记录、哪些限制查阅，没有写移交的日期。</p><p>从这件事看<strong>有序退场的完成条件</strong>：记录有了接收方，只是七个完成面中“记忆与证据”一面的局部材料；其余各面没有材料时，整体记为未知，不写完成，也不写失败。</p><p><a href="./atlantic-archives-exit.html">阅读大西洋慈善基金会档案案例 →</a></p><h2 id="怎样使用这些案例" tabindex="-1">怎样使用这些案例 <a class="header-anchor" href="#怎样使用这些案例" aria-label="Permalink to &quot;怎样使用这些案例&quot;">​</a></h2><p>读一个案例时，保留三个问题：来源实际证明了什么？概念帮助区分了什么？还有哪些结论不能从这件事推出？一个案例能澄清某个区别，并不自动证明它适用于所有组织与所有情形。</p><p>需要先了解概念，可以进入<a href="./../concepts/">概念图解</a>；需要核对定义，可以回到<a href="./../theory/">理论原文</a>。</p>',39)])])}const m=e(n,[["render",h]]);export{f as __pageData,m as default};
